-- Printer round-trip tests: parse, print without transforms, compare with Go's output.
-- "TestEmit" cases are copied from Go internal/printer/printer_test.go; the "comments and
-- whitespace" cases were generated by running the Go printer (PrinterOptions{NewLine: LF}, and
-- RemoveComments for the second expectation) on the same inputs.
local core = require("tslua.core")
local parser = require("tslua.parser")
local printer = require("tslua.printer")

local function parseTypeScript(text, jsx)
    local fileName = jsx and "/main.tsx" or "/main.ts"
    return parser.ParseSourceFile({ fileName = fileName, path = fileName, externalModuleIndicatorOptions = { jsx = false, force = false } }, text, core.GetScriptKindFromFileName(fileName))
end

local function emit(file, removeComments)
    local p = printer.NewPrinter({ newLine = core.NewLineKind.LF, removeComments = removeComments }, {}, nil)
    local text = p:EmitSourceFile(file)
    if text:sub(-1) == "\n" then
        text = text:sub(1, -2)
    end
    return text
end

