    { "block comments", "/* a */ let x = /* b */ 1 /* c */;", "/* a */ let x = /* b */ 1 /* c */;", "let x = 1;" },
    { "detached copyright header", "/*! copyright */\n\n// detached\n\nlet x;", "/*! copyright */\n// detached\nlet x;", "/*! copyright */\nlet x;" },
    { "jsdoc on function", "/**\n * Doc\n * @param a thing\n */\nfunction f(a) {\n    // inside\n    return a; // trailing\n}", "/**\n * Doc\n * @param a thing\n */\nfunction f(a) {\n    // inside\n    return a; // trailing\n}", "function f(a) {\n    return a;\n}" },
    { "comment in empty block", "function f() {\n    // nothing\n}", "function f() {\n    // nothing\n}", "function f() {\n}" },
    { "comments in object literal", "const o = {\n    // first\n    a: 1, // after a\n    /* b */ b: 2\n};", "const o = {\n    // first\n    a: 1, // after a\n    /* b */ b: 2\n};", "const o = {\n    a: 1,\n    b: 2\n};" },
    { "blank lines preserved between statements", "let a;\n\n\nlet b;\nlet c;", "let a;\nlet b;\nlet c;", "let a;\nlet b;\nlet c;" },
    { "class with members", "class C<T> extends B implements I {\n    private x: number = 1;\n    constructor(public y: string) { super(); }\n    get z() { return 1; }\n    static m(): void {}\n}", "class C<T> extends B implements I {\n    private x: number = 1;\n    constructor(public y: string) { super(); }\n    get z() { return 1; }\n    static m(): void { }\n}", "class C<T> extends B implements I {\n    private x: number = 1;\n    constructor(public y: string) { super(); }\n    get z() { return 1; }\n    static m(): void { }\n}" },
    { "multiline array", "const a = [\n    1,\n    2,\n];", "const a = [\n    1,\n    2,\n];", "const a = [\n    1,\n    2,\n];" },
    { "indentation of nested blocks", "if (a) {\nif (b) {\nc();\n}\n} else if (d) e(); else { f() }", "if (a) {\n    if (b) {\n        c();\n    }\n}\nelse if (d)\n    e();\nelse {\n    f();\n}", "if (a) {\n    if (b) {\n        c();\n    }\n}\nelse if (d)\n    e();\nelse {\n    f();\n}" },
    { "shebang", "#!/usr/bin/env node\nconsole.log(1);", "#!/usr/bin/env node\nconsole.log(1);", "#!/usr/bin/env node\nconsole.log(1);" },
    { "triple slash", "/// <reference path=\"a.ts\" />\nlet x;", "/// <reference path=\"a.ts\" />\nlet x;", "let x;" },
    { "switch", "switch (x) {\n    case 1:\n    case 2: y(); break;\n    default:\n        // none\n}", "switch (x) {\n    case 1:\n    case 2:\n        y();\n        break;\n    default:\n    // none\n}", "switch (x) {\n    case 1:\n    case 2:\n        y();\n        break;\n    default:\n}" },
    { "template and regex", "const s = `a${b}c${d}`; const r = /ab+c/gi;", "const s = `a${b}c${d}`;\nconst r = /ab+c/gi;", "const s = `a${b}c${d}`;\nconst r = /ab+c/gi;" },
    { "types", "type T = { a: string; b?: number } | [x: number, ...y: string[]] | ((a: number) => void) | keyof typeof x;", "type T = {\n    a: string;\n    b?: number;\n} | [\n    x: number,\n    ...y: string[]\n] | ((a: number) => void) | keyof typeof x;", "type T = {\n    a: string;\n    b?: number;\n} | [\n    x: number,\n    ...y: string[]\n] | ((a: number) => void) | keyof typeof x;" },
    { "arrow and async", "const f = async (a, b = 1, ...c) => { await a; };\nconst g = x => x * 2;", "const f = async (a, b = 1, ...c) => { await a; };\nconst g = x => x * 2;", "const f = async (a, b = 1, ...c) => { await a; };\nconst g = x => x * 2;" },
    { "string escapes", "const s = \"\\u00e9\\n\\t\" + 'it\\'s' + \"é\";", "const s = \"\\u00e9\\n\\t\" + 'it\\'s' + \"é\";", "const s = \"\\u00e9\\n\\t\" + 'it\\'s' + \"é\";" },
    { "enum and namespace", "enum E { A = 1, B, C = \"c\" }\nnamespace N.M { export const x = 1; }\ndeclare module \"m\" { }", "enum E {\n    A = 1,\n    B,\n    C = \"c\"\n}\nnamespace N.M {\n    export const x = 1;\n}\ndeclare module \"m\" { }", "enum E {\n    A = 1,\n    B,\n    C = \"c\"\n}\nnamespace N.M {\n    export const x = 1;\n}\ndeclare module \"m\" { }" },
    { "imports exports", "import a, { b as c, type d } from \"mod\";\nimport * as ns from 'ns';\nexport { a, c as default };\nexport * from \"x\";\nexport default function () {}", "import a, { b as c, type d } from \"mod\";\nimport * as ns from 'ns';\nexport { a, c as default };\nexport * from \"x\";\nexport default function () { }", "import a, { b as c, type d } from \"mod\";\nimport * as ns from 'ns';\nexport { a, c as default };\nexport * from \"x\";\nexport default function () { }" },
    { "unicode identifiers and comments", "// ünïcödé 💩\nconst π = 3.14; /* 日本 */", "// ünïcödé 💩\nconst π = 3.14; /* 日本 */", "const π = 3.14;" },
    { "crlf input", "let a = 1;\r\n// c\r\nlet b = 2;\r\n", "let a = 1;\n// c\nlet b = 2;", "let a = 1;\nlet b = 2;" },
}

describe("printer", function()
    describe("TestEmit", function()
        for _, c in ipairs(emitCases) do
            local title, input, expected, jsx = c[1], c[2], c[3], c[4] or false
            it(title, function()
                local file = parseTypeScript(input, jsx)
                assert.are.equal(0, #file:Diagnostics())
                assert.are.equal(expected, emit(file, false))
            end)
        end
    end)

    describe("comments and whitespace", function()
        for _, c in ipairs(triviaCases) do
            local title, input, expected, expectedNoComments, jsx = c[1], c[2], c[3], c[4], c[5] or false
            it(title, function()
                local file = parseTypeScript(input, jsx)
                assert.are.equal(expected, emit(file, false))
                assert.are.equal(expectedNoComments, emit(file, true))
            end)
        end
    end)

    it("OmitTrailingSemicolon", function()
        local file = parseTypeScript("for (;;) {}", false)
        local p = printer.NewPrinter({ newLine = core.NewLineKind.LF, omitTrailingSemicolon = true }, {}, nil)
        local text = p:EmitSourceFile(file)
        if text:sub(-1) == "\n" then
            text = text:sub(1, -2)
        end
        assert.are.equal("for (;;) { }", text)
    end)
end)
